def vision_health(timeout_seconds: float = 0.35) -> dict[str, Any]:
    try:
        with urllib.request.urlopen(
            "http://127.0.0.1:8000/api/v1/vision/health", timeout=timeout_seconds
        ) as response:
            payload = json.loads(response.read(128 * 1024).decode("utf-8"))
            return {"online": response.status == 200, "status_code": response.status, "health": payload}
    except (OSError, ValueError, urllib.error.URLError) as exc:
        return {"online": False, "status_code": None, "health": None, "error": str(exc)[:160]}


